export function mountQAReadyBanner(root){const label=root.ownerDocument.createElement('p');label.dataset.qaReady='QA_READY_NO_STORAGE';label.setAttribute('role','note');label.textContent='QA_READY_NO_STORAGE · 성소3/나침반 정식 행동으로 준비한 메모리 검수 · 최종대결은 직접 조작 · 일반 저장/완전 플레이 인증 아님';Object.assign(label.style,{background:'#ffc400',color:'#111',fontWeight:'900',padding:'12px',border:'3px solid #111',position:'relative',zIndex:'5'});root.prepend(label);return()=>label.remove()}
